const HANDLE_INDEX_MASK: u64 = u32::MAX as u64;

#[derive(Debug)]
enum HandleError {
    InvalidZero,
    UnknownSlot,
    StaleGeneration,
    WrongType,
    RegistryPoisoned,
    HandleBusy,
    AliasedHandle,
}

impl std::fmt::Display for HandleError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let message = match self {
            Self::InvalidZero => "zero is not a valid handle",
            Self::UnknownSlot => "handle refers to an unknown slot",
            Self::StaleGeneration => "handle generation is stale",
            Self::WrongType => "handle has the wrong type",
            Self::RegistryPoisoned => "handle registry lock is poisoned",
            Self::HandleBusy => "handle is currently in use",
            Self::AliasedHandle => "the same handle was passed more than once",
        };
        formatter.write_str(message)
    }
}

type ErasedHandleValue = std::sync::Arc<std::sync::Mutex<Box<dyn std::any::Any + Send>>>;

struct HandleSlot {
    generation: u32,
    type_id: std::any::TypeId,
    value: Option<ErasedHandleValue>,
}

#[derive(Default)]
struct HandleRegistry {
    slots: Vec<HandleSlot>,
}

impl HandleRegistry {
    fn insert<T: std::any::Any + Send>(&mut self, value: T) -> AlefHandle {
        let entry = std::sync::Arc::new(std::sync::Mutex::new(Box::new(value) as Box<dyn std::any::Any + Send>));
        let type_id = std::any::TypeId::of::<T>();
        if let Some((index, slot)) = self.slots.iter_mut().enumerate().find(|(_, slot)| slot.value.is_none()) {
            slot.type_id = type_id;
            slot.value = Some(entry);
            return encode_handle(index, slot.generation);
        }
        self.slots.push(HandleSlot {
            generation: 1,
            type_id,
            value: Some(entry),
        });
        encode_handle(self.slots.len() - 1, 1)
    }

    fn get(&self, handle: AlefHandle) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        slot.value.clone().ok_or(HandleError::StaleGeneration)
    }

    fn get_typed(&self, handle: AlefHandle, expected_type: std::any::TypeId) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        let value = slot.value.as_ref().ok_or(HandleError::StaleGeneration)?;
        if slot.type_id != expected_type {
            return Err(HandleError::WrongType);
        }
        Ok(value.clone())
    }

    fn detach<T: std::any::Any + Send>(&mut self, handle: AlefHandle) -> Result<ErasedHandleValue, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get_mut(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        if slot.value.is_none() {
            return Err(HandleError::StaleGeneration);
        }
        if slot.type_id != std::any::TypeId::of::<T>() {
            return Err(HandleError::WrongType);
        }
        let value = slot.value.take().ok_or(HandleError::StaleGeneration)?;
        slot.generation = next_generation(slot.generation);
        Ok(value)
    }

    fn take<T: std::any::Any + Send>(&mut self, handle: AlefHandle) -> Result<T, HandleError> {
        let (index, generation) = decode_handle(handle)?;
        let slot = self.slots.get_mut(index).ok_or(HandleError::UnknownSlot)?;
        if slot.generation != generation {
            return Err(HandleError::StaleGeneration);
        }
        if slot.value.is_none() {
            return Err(HandleError::StaleGeneration);
        }
        if slot.type_id != std::any::TypeId::of::<T>() {
            return Err(HandleError::WrongType);
        }
        let value = slot.value.take().ok_or(HandleError::StaleGeneration)?;
        let mutex = std::sync::Arc::try_unwrap(value).map_err(|value| {
            slot.value = Some(value);
            HandleError::HandleBusy
        })?;
        slot.generation = next_generation(slot.generation);
        let boxed = mutex.into_inner().map_err(|_| HandleError::RegistryPoisoned)?;
        boxed
            .downcast::<T>()
            .map(|value| *value)
            .map_err(|_| HandleError::WrongType)
    }
}

static HANDLE_REGISTRY: std::sync::OnceLock<std::sync::Mutex<HandleRegistry>> = std::sync::OnceLock::new();

fn handle_registry() -> &'static std::sync::Mutex<HandleRegistry> {
    HANDLE_REGISTRY.get_or_init(|| std::sync::Mutex::new(HandleRegistry::default()))
}

fn insert_handle<T: std::any::Any + Send>(value: T) -> Result<AlefHandle, HandleError> {
    let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    Ok(registry.insert(value))
}

struct SerializedHandle<T: 'static> {
    json: String,
    marker: std::marker::PhantomData<fn() -> T>,
}

fn insert_serialized_handle<T: serde::Serialize + 'static>(value: &T) -> Result<AlefHandle, String> {
    let json = serde_json::to_string(value).map_err(|error| error.to_string())?;
    insert_handle(SerializedHandle::<T> {
        json,
        marker: std::marker::PhantomData,
    })
    .map_err(|error| error.to_string())
}

fn with_handle<T: std::any::Any + Send, R>(
    handle: AlefHandle,
    operation: impl FnOnce(&T) -> R,
) -> Result<R, HandleError> {
    let value = {
        let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.get(handle)?
    };
    let guard = value.lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let typed = guard.downcast_ref::<T>().ok_or(HandleError::WrongType)?;
    Ok(operation(typed))
}

struct HandleRequest {
    handle: AlefHandle,
    expected_type: std::any::TypeId,
}

fn acquire_handles(requests: &[HandleRequest]) -> Result<Vec<(AlefHandle, ErasedHandleValue)>, HandleError> {
    let mut ordered = requests.iter().collect::<Vec<_>>();
    ordered.sort_by_key(|request| request.handle);
    if ordered.windows(2).any(|pair| pair[0].handle == pair[1].handle) {
        return Err(HandleError::AliasedHandle);
    }
    let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let mut values = Vec::with_capacity(ordered.len());
    for request in ordered {
        values.push((
            request.handle,
            registry.get_typed(request.handle, request.expected_type)?,
        ));
    }
    Ok(values)
}

fn locked_handle_ptr<T: std::any::Any + Send>(
    guards: &mut [(AlefHandle, std::sync::MutexGuard<'_, Box<dyn std::any::Any + Send>>)],
    handle: AlefHandle,
) -> Result<*mut T, HandleError> {
    let (_, guard) = guards
        .iter_mut()
        .find(|(candidate, _)| *candidate == handle)
        .ok_or(HandleError::UnknownSlot)?;
    guard
        .downcast_mut::<T>()
        .map(|value| value as *mut T)
        .ok_or(HandleError::WrongType)
}

fn with_handle_mut<T: std::any::Any + Send, R>(
    handle: AlefHandle,
    operation: impl FnOnce(&mut T) -> R,
) -> Result<R, HandleError> {
    let value = {
        let registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.get(handle)?
    };
    let mut guard = value.lock().map_err(|_| HandleError::RegistryPoisoned)?;
    let typed = guard.downcast_mut::<T>().ok_or(HandleError::WrongType)?;
    Ok(operation(typed))
}

// Freeing is deferred destruction: the slot is detached at once, so every later use of the
// handle fails as stale, but the object is dropped by whoever releases the last `Arc`. A call that
// is still running holds one, so `T::drop` runs when that call returns (on its thread), never
// under it. The drop happens outside the registry lock so a `Drop` impl cannot deadlock on it.
fn remove_handle<T: std::any::Any + Send>(handle: AlefHandle) -> Result<(), HandleError> {
    let detached = {
        let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
        registry.detach::<T>(handle)?
    };
    drop(detached);
    Ok(())
}

fn take_handle<T: std::any::Any + Send>(handle: AlefHandle) -> Result<T, HandleError> {
    let mut registry = handle_registry().lock().map_err(|_| HandleError::RegistryPoisoned)?;
    registry.take::<T>(handle)
}

fn encode_handle(index: usize, generation: u32) -> AlefHandle {
    ((generation as u64) << 32) | ((index as u64) + 1)
}

fn decode_handle(handle: AlefHandle) -> Result<(usize, u32), HandleError> {
    if handle == 0 {
        return Err(HandleError::InvalidZero);
    }
    let encoded_index = handle & HANDLE_INDEX_MASK;
    if encoded_index == 0 {
        return Err(HandleError::UnknownSlot);
    }
    Ok(((encoded_index - 1) as usize, (handle >> 32) as u32))
}

fn next_generation(generation: u32) -> u32 {
    let next = generation.wrapping_add(1);
    if next == 0 { 1 } else { next }
}

fn set_handle_error(error: &HandleError) {
    set_last_error(ALEF_INVALID_HANDLE_ERROR, &error.to_string());
}

/// Free a string previously returned by this library.
/// # Safety
/// Pointer must have been returned by this library, or be null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_free_string(ptr: *mut c_char) {
    catch_ffi_panic((), || {
        if !ptr.is_null() {
            // SAFETY: ptr was allocated by CString::into_raw; caller ensures no aliases.
            unsafe {
                drop(CString::from_raw(ptr));
            }
        }
    })
}

/// Free a byte buffer previously returned by this library via out-params.
/// `ptr`, `len`, and `cap` must match the values written by the library function,
/// or the call must pass `ptr = null` (in which case it is a no-op).
/// # Safety
/// Pointer must have been returned by this library (via out_ptr / out_len / out_cap
/// out-params), and ownership must not already have been released.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_free_bytes(ptr: *mut u8, len: usize, cap: usize) {
    catch_ffi_panic((), || {
        if ptr.is_null() {
            return;
        }
        if len != cap {
            set_last_error(1, "invalid byte buffer metadata: len and cap differ");
            return;
        }
        // SAFETY: The library returns a Box<[u8]> allocation and reports its length
        // as both len and cap; the caller contract preserves pointer and ownership.
        unsafe {
            let slice = std::ptr::slice_from_raw_parts_mut(ptr, len);
            drop(Box::<[u8]>::from_raw(slice));
        }
    })
}

/// Return the library version string. The pointer is static and must NOT be freed.
/// # Safety
/// Caller must ensure all pointer arguments are valid or null.
/// Returned pointers must be freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_version() -> *const c_char {
    catch_ffi_panic(std::ptr::null(), || {
        static VERSION: &str = concat!(env!("CARGO_PKG_VERSION"), "\0");
        VERSION.as_ptr() as *const c_char
    })
}

/// Callback invoked for each streamed chunk.
/// `chunk_json` is a JSON-encoded chunk; `user_data` is forwarded from the caller.
pub type LiterllmStreamCallback =
    unsafe extern "C" fn(chunk_json: *const std::ffi::c_char, user_data: *mut std::ffi::c_void);

/// Opaque handle owning a tokio runtime and a boxed chat-stream for iterator-style consumption.
///
/// Created by `literllm_default_client_chat_stream_start`, advanced by `literllm_default_client_chat_stream_next`, destroyed by `literllm_default_client_chat_stream_free`.
/// The handle is NOT thread-safe — callers must ensure only one thread calls `_next` at a time.
pub struct LiterllmDefaultClientChatStreamStreamHandle {
    rt: tokio::runtime::Runtime,
    stream: std::sync::Mutex<
        Option<
            futures_util::stream::BoxStream<
                'static,
                Result<liter_llm::ChatCompletionChunk, Box<dyn std::error::Error + Send + Sync + 'static>>,
            >,
        >,
    >,
    cancel: Option<std::sync::Arc<AlefCancelState>>,
}

/// Start a streaming chat completion and return an opaque iterator handle.
///
/// Returns null and sets `literllm_last_error_code` on failure (null pointers or stream-open error).
/// On success the caller owns the returned pointer and MUST call `literllm_default_client_chat_stream_free` when done.
///
/// # Safety
/// `client` must be a non-null valid pointer to a live `liter_llm::DefaultClient` produced by this library.
/// `req` must be a non-null valid pointer to a live `liter_llm::ChatCompletionRequest` produced by this library.
/// Both pointers must remain valid until this function returns.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_default_client_chat_stream_start(client: AlefHandle, req: AlefHandle) -> AlefHandle {
    catch_ffi_panic(0, || {
        clear_last_error();
        // SAFETY: the caller upholds this function's contract, which `literllm_default_client_chat_stream_start_open` shares.
        unsafe { literllm_default_client_chat_stream_start_open(client, req, None) }
    })
}

/// Start a streaming chat completion that a cancel token can abort, and return an opaque iterator handle.
///
/// Behaves exactly like `literllm_default_client_chat_stream_start`, and additionally tripping `alef_cancel_token` (created by
/// `literllm_cancel_token_new`, `0` for none) aborts both the stream-open request and any later
/// blocking `literllm_default_client_chat_stream_next` call on the returned handle: each returns null with last-error code
/// `Cancelled`. The handle keeps its own reference to the token, so the token may be freed
/// before the handle is.
///
/// # Safety
/// Same contract as `literllm_default_client_chat_stream_start`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_default_client_chat_stream_start_cancellable(
    client: AlefHandle,
    req: AlefHandle,
    alef_cancel_token: AlefHandle,
) -> AlefHandle {
    catch_ffi_panic(0, || {
        clear_last_error();
        let cancel = match alef_cancel_state(alef_cancel_token) {
            Ok(state) => state,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the caller upholds this function's contract, which `literllm_default_client_chat_stream_start_open` shares.
        unsafe { literllm_default_client_chat_stream_start_open(client, req, cancel) }
    })
}

unsafe fn literllm_default_client_chat_stream_start_open(
    client: AlefHandle,
    req: AlefHandle,
    cancel: Option<std::sync::Arc<AlefCancelState>>,
) -> AlefHandle {
    let requests = [
        HandleRequest {
            handle: client,
            expected_type: std::any::TypeId::of::<liter_llm::DefaultClient>(),
        },
        HandleRequest {
            handle: req,
            expected_type: std::any::TypeId::of::<liter_llm::ChatCompletionRequest>(),
        },
    ];
    let values = match acquire_handles(&requests) {
        Ok(values) => values,
        Err(error) => {
            set_handle_error(&error);
            return 0;
        }
    };
    let mut guards = Vec::with_capacity(values.len());
    for (token, value) in &values {
        match alef_lock_handle(value, cancel.as_deref()) {
            Some(guard) => guards.push((*token, guard)),
            None => return 0,
        }
    }
    let client_ptr = match locked_handle_ptr::<liter_llm::DefaultClient>(&mut guards, client) {
        Ok(value) => value,
        Err(error) => {
            set_handle_error(&error);
            return 0;
        }
    };
    let request_ptr = match locked_handle_ptr::<liter_llm::ChatCompletionRequest>(&mut guards, req) {
        Ok(value) => value,
        Err(error) => {
            set_handle_error(&error);
            return 0;
        }
    };
    // SAFETY: both registry entry guards remain held for the duration of this call.
    let client_ref = unsafe { &*client_ptr };
    // SAFETY: both registry entry guards remain held for the duration of this call.
    let req_owned = unsafe { &*request_ptr }.clone();

    // 16 MiB: tokio's ~2 MB default worker stack can overflow on a deep extraction
    // future (a nested archive member, a multi-stage OCR pipeline), and a stack overflow
    // aborts the process with SIGBUS instead of raising a catchable panic.
    const STREAM_HANDLE_RUNTIME_STACK_SIZE_BYTES: usize = 16 * 1024 * 1024;
    let rt = match tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .thread_stack_size(STREAM_HANDLE_RUNTIME_STACK_SIZE_BYTES)
        .build()
    {
        Ok(r) => r,
        Err(e) => {
            set_last_error(
                99,
                &format!("literllm_default_client_chat_stream_start: failed to create tokio runtime: {e}"),
            );
            return 0;
        }
    };

    let stream_result = match alef_block_on_in(&rt, cancel.as_ref(), async { client_ref.chat_stream(req_owned).await })
    {
        Some(result) => result,
        None => return 0,
    };

    let raw_stream = match stream_result {
        Ok(s) => s,
        Err(e) => {
            set_last_error_from(
                &e,
                &format!("literllm_default_client_chat_stream_start: failed to open stream: {e}"),
            );
            return 0;
        }
    };

    // Map the stream's concrete error type to Box<dyn Error> to erase it from the handle type.
    let mapped: futures_util::stream::BoxStream<
        'static,
        Result<liter_llm::ChatCompletionChunk, Box<dyn std::error::Error + Send + Sync + 'static>>,
    > = {
        use futures_util::StreamExt;
        Box::pin(raw_stream.map(|r| r.map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync + 'static>)))
    };

    let handle = LiterllmDefaultClientChatStreamStreamHandle {
        rt,
        stream: std::sync::Mutex::new(Some(mapped)),
        cancel,
    };
    match insert_handle(handle) {
        Ok(handle) => handle,
        Err(error) => {
            set_handle_error(&error);
            0
        }
    }
}

/// Advance the stream and return a heap-allocated chunk, or null.
///
/// Returns null in two cases:
/// - Clean end-of-stream: `literllm_last_error_code()` returns 0.
/// - Stream error: `literllm_last_error_code()` returns non-zero.
///
/// The returned pointer is heap-allocated and the caller MUST free it by calling
/// `literllm_default_client_ChatCompletionChunk_free` (or the appropriate type-free function).
///
/// # Safety
/// `handle` must be a non-null valid pointer previously returned by `literllm_default_client_chat_stream_start` and not yet
/// freed. Calling `_next` after `_free` is undefined behaviour. The handle must not be shared
/// across threads without external synchronisation.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_default_client_chat_stream_next(handle: AlefHandle) -> AlefHandle {
    catch_ffi_panic(0, || {
        clear_last_error();

        let value = match acquire_handles(&[HandleRequest {
            handle,
            expected_type: std::any::TypeId::of::<LiterllmDefaultClientChatStreamStreamHandle>(),
        }]) {
            Ok(mut values) => match values.pop() {
                Some(value) => value,
                None => {
                    set_handle_error(&HandleError::UnknownSlot);
                    return 0;
                }
            },
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let h_guard = match value.1.lock() {
            Ok(guard) => guard,
            Err(_) => {
                set_handle_error(&HandleError::RegistryPoisoned);
                return 0;
            }
        };
        let h = match h_guard.downcast_ref::<LiterllmDefaultClientChatStreamStreamHandle>() {
            Some(value) => value,
            None => {
                set_handle_error(&HandleError::WrongType);
                return 0;
            }
        };

        let mut guard = match h.stream.lock() {
            Ok(g) => g,
            Err(_) => {
                set_last_error(99, "literllm_default_client_chat_stream_next: stream mutex is poisoned");
                return 0;
            }
        };

        let stream = match guard.as_mut() {
            Some(s) => s,
            None => {
                // Stream already exhausted or taken.
                return 0;
            }
        };

        use futures_util::StreamExt;
        let next = match alef_block_on_in(&h.rt, h.cancel.as_ref(), stream.next()) {
            Some(next) => next,
            None => return 0,
        };
        match next {
            Some(Ok(chunk)) => {
                // SAFETY: We box the chunk and transfer ownership to the caller via raw pointer.
                // The caller must free it via the appropriate type-free function.
                match insert_handle(chunk) {
                    Ok(handle) => handle,
                    Err(error) => {
                        set_handle_error(&error);
                        0
                    }
                }
            }
            Some(Err(e)) => {
                set_last_error(
                    99,
                    &format!("literllm_default_client_chat_stream_next: stream error: {e}"),
                );
                0
            }
            None => {
                // Clean end-of-stream — error code remains 0 (cleared at top of function).
                *guard = None;
                0
            }
        }
    })
}

/// Free a stream handle created by `literllm_default_client_chat_stream_start`.
///
/// Safe to call with a null pointer (no-op). After this call the handle pointer is invalid.
///
/// # Safety
/// `handle` must either be null or a valid pointer previously returned by `literllm_default_client_chat_stream_start` and
/// not yet freed. Double-free is undefined behaviour.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_default_client_chat_stream_free(handle: AlefHandle) {
    catch_ffi_panic((), || {
        if handle != 0
            && let Err(error) = remove_handle::<LiterllmDefaultClientChatStreamStreamHandle>(handle)
        {
            set_handle_error(&error);
        }
    })
}

