/// Count tokens for a full `ChatCompletionRequest`.
///
/// Sums tokens across all message text contents plus a per-message overhead
/// of ~4 tokens (for role, separators, and formatting metadata). Tool
/// definitions and multimodal content parts (images, audio, documents) are
/// not counted â only textual content contributes to the token total.
/// \note Returns `LiterLlmError.BadRequest` if the tokenizer cannot be loaded or
/// if tokenization fails for any message.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[cfg(feature = "tokenizer")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_count_request_tokens(model: *const std::ffi::c_char, req: AlefHandle) -> usize {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: req,
            expected_type: std::any::TypeId::of::<liter_llm::types::ChatCompletionRequest>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if model.is_null() {
            set_last_error(1, "Null pointer passed for parameter 'model'");
            return 0;
        }
        // SAFETY: null check above guarantees model is a valid pointer; string is valid UTF-8 from caller.
        let model_rs = match unsafe { CStr::from_ptr(model) }.to_str() {
            Ok(s) => s.to_string(),
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in parameter 'model'");
                return 0;
            }
        };

        if req == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'req'",
            );
            return 0;
        }
        let req_rs_ptr = match locked_handle_ptr::<liter_llm::types::ChatCompletionRequest>(&mut __alef_guards, req) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let req_rs = unsafe { &*req_rs_ptr };

        let result = liter_llm::count_request_tokens(&model_rs, &req_rs);
        match result {
            Ok(val) => val,
            Err(e) => {
                set_last_error_from(&e, &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

