/// Encode bytes as a base64 data URL: `data:<mime>;base64,<b64>`.
///
/// `mime` defaults to `IMAGE_PNG` when `None`.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
/// \code
/// use liter_llm::image::{encode_data_url, IMAGE_PNG, IMAGE_JPEG};
///
/// let url = encode_data_url(b"\x89PNG", Some(IMAGE_PNG));
/// assert!(url.starts_with("data:image/png;base64,"));
///
/// let url_default = encode_data_url(b"\x89PNG", None);
/// assert!(url_default.starts_with("data:image/png;base64,"));
///
/// let jpeg_url = encode_data_url(b"\xff\xd8\xff", Some(IMAGE_JPEG));
/// assert!(jpeg_url.starts_with("data:image/jpeg;base64,"));
/// \endcode
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_encode_data_url(
    bytes: *const u8,
    bytes_len: usize,
    mime: *const std::ffi::c_char,
) -> *mut std::ffi::c_char {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        set_last_return_len("literllm_encode_data_url", 0);
        if bytes.is_null() && bytes_len > 0 {
            set_last_error(1, "Null pointer passed for parameter 'bytes'");
            return std::ptr::null_mut();
        }
        // SAFETY: when bytes is null, bytes_len is 0 (checked above), so we use an empty slice; otherwise data is valid for len elements.
        let bytes_rs = if bytes.is_null() {
            Vec::new()
        } else {
            unsafe { std::slice::from_raw_parts(bytes, bytes_len) }.to_vec()
        };

        let mime_rs = if mime.is_null() {
            None
        } else {
            // SAFETY: null check above guarantees mime is a valid pointer; string is valid UTF-8 from caller.
            match unsafe { CStr::from_ptr(mime) }.to_str() {
                Ok(s) => Some(s.to_string()),
                Err(_) => {
                    set_last_error(1, "Invalid UTF-8 in parameter 'mime'");
                    return std::ptr::null_mut();
                }
            }
        };

        let result = liter_llm::image::encode_data_url(&bytes_rs, mime_rs.as_deref());
        {
            let __alef_return = result.to_string();
            match CString::new(__alef_return) {
                Ok(cs) => {
                    set_last_return_len("literllm_encode_data_url", cs.as_bytes().len());
                    cs.into_raw()
                }
                Err(_) => {
                    set_last_return_len("literllm_encode_data_url", 0);
                    std::ptr::null_mut()
                }
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            std::ptr::null_mut()
        }
    }
}

