/// Cancellable variant of `literllm_refresh_catalog`.
///
/// Takes a trailing `alef_cancel_token` created by `literllm_cancel_token_new`. Tripping it with
/// `literllm_cancel_token_cancel` from any thread aborts the blocking call, which then fails with the
/// `Cancelled` error code. Pass `0` for a call that is never cancelled.
///
/// Refresh the runtime catalog overlay per `config`.
///
/// - `config.enabled == false`: returns `Ok(``RefreshOutcome.Disabled``)`
///   immediately. No network, filesystem, or overlay activity.
/// - A fresh on-disk cache (age < `config.ttl_seconds`) exists at the
///   resolved cache path (`config.cache_path`, or a default under
///   `std::env::temp_dir()`): read + flatten it and install the overlay,
///   returning `Ok(``RefreshOutcome.FromCache``)`. No network request is
///   made.
/// - Otherwise: validate `config.source_url` uses `https`
///   (`CatalogRefreshError.InsecureUrl` otherwise), fetch it, flatten it,
///   install the overlay, best-effort write the raw JSON to the cache path
///   (a cache write failure does not fail the refresh), and return
///   `Ok(``RefreshOutcome.Fetched``)`.
///
/// On any error return, the overlay is left untouched: the previously
/// active registry (a prior successful overlay, or the embedded catalog if
/// none was ever installed) remains in effect. This is what makes the
/// feature air-gap-safe â an unreachable or invalid `source_url` never
/// degrades `completion_cost` / `model_info` below embedded-catalog
/// availability.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_refresh_catalog_cancellable(
    config: AlefHandle,
    alef_cancel_token: AlefHandle,
) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let alef_cancel = match alef_cancel_state(alef_cancel_token) {
            Ok(state) => state,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<liter_llm::CatalogRefreshConfig>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match alef_lock_handle(value, alef_cancel.as_deref()) {
                Some(guard) => __alef_guards.push((*handle, guard)),
                None => {
                    return 0;
                }
            }
        }
        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return 0;
        }
        let config_rs_ptr = match locked_handle_ptr::<liter_llm::CatalogRefreshConfig>(&mut __alef_guards, config) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr };

        let result = match alef_block_on_in(get_ffi_runtime(), alef_cancel.as_ref(), async {
            liter_llm::refresh_catalog(&config_rs).await
        }) {
            Some(value) => value,
            None => {
                return 0;
            }
        };
        match result {
            Ok(val) => match insert_handle(val) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(e) => {
                set_last_error_from(&e, &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

/// Register a custom provider in the global runtime registry.
///
/// The provider will be checked **before** all built-in providers during model
/// detection. If a provider with the same `name` already exists it is replaced.
/// \note Returns an error if the config is invalid (empty name, empty base_url, or
/// no model prefixes).
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_register_custom_provider(config: AlefHandle) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: config,
            expected_type: std::any::TypeId::of::<liter_llm::provider::custom::CustomProviderConfig>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return -1;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return -1;
                }
            }
        }
        if config == 0 {
            set_last_error(
                ALEF_INVALID_HANDLE_ERROR,
                "zero is not a valid handle for parameter 'config'",
            );
            return -1;
        }
        let config_rs_ptr =
            match locked_handle_ptr::<liter_llm::provider::custom::CustomProviderConfig>(&mut __alef_guards, config) {
                Ok(value) => value,
                Err(error) => {
                    set_handle_error(&error);
                    return -1;
                }
            };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let config_rs = unsafe { &*config_rs_ptr }.clone();

        let result = liter_llm::provider::custom::register_custom_provider(config_rs);
        match result {
            Ok(()) => 0,
            Err(e) => {
                set_last_error_from(&e, &e.to_string());
                -1
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            -1
        }
    }
}

/// Remove a previously registered custom provider by name.
///
/// Returns `true` if a provider with the given name was found and removed,
/// `false` if no such provider existed.
/// \note Returns an error if the custom-provider registry cannot be updated.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_unregister_custom_provider(name: *const std::ffi::c_char) -> i32 {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if name.is_null() {
            set_last_error(1, "Null pointer passed for parameter 'name'");
            return 0;
        }
        // SAFETY: null check above guarantees name is a valid pointer; string is valid UTF-8 from caller.
        let name_rs = match unsafe { CStr::from_ptr(name) }.to_str() {
            Ok(s) => s.to_string(),
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in parameter 'name'");
                return 0;
            }
        };

        let result = liter_llm::provider::custom::unregister_custom_provider(&name_rs);
        match result {
            Ok(val) => {
                if val {
                    1
                } else {
                    0
                }
            }
            Err(e) => {
                set_last_error_from(&e, &e.to_string());
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

/// Return the HTTP status code for the error pointed to by `err`.
/// Returns `0` if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_liter_llm_error_status_code(err: *const liter_llm::LiterLlmError) -> u16 {
    if err.is_null() {
        return 0;
    }
    // SAFETY: caller guarantees `err` points to a live `liter_llm::LiterLlmError` value
    // allocated by this library, or is null (checked above).
    unsafe { (*err).status_code() }
}

// Not emitted: FFI helper for method `retry_after` on `liter_llm::LiterLlmError`

/// Return whether the error pointed to by `err` is transient.
/// Returns `false` if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_liter_llm_error_is_transient(err: *const liter_llm::LiterLlmError) -> bool {
    if err.is_null() {
        return false;
    }
    // SAFETY: caller guarantees `err` points to a live `liter_llm::LiterLlmError` value
    // allocated by this library, or is null (checked above).
    unsafe { (*err).is_transient() }
}

/// Return the machine-readable error category string for the error pointed
/// to by `err` as a heap-allocated, NUL-terminated C string.
/// The caller must free the returned pointer with `literllm_liter_llm_error_error_type_free`.
/// Returns a null pointer if `err` is null.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_liter_llm_error_error_type(
    err: *const liter_llm::LiterLlmError,
) -> *mut std::ffi::c_char {
    if err.is_null() {
        return std::ptr::null_mut();
    }
    // SAFETY: caller guarantees `err` points to a live `liter_llm::LiterLlmError` value
    // allocated by this library, or is null (checked above).
    let s = unsafe { (*err).error_type() };
    // SAFETY: `error_type()` returns a `'static str` containing no NUL bytes.
    std::ffi::CString::new(s)
        .map(|c| c.into_raw())
        .unwrap_or(std::ptr::null_mut())
}

/// Free a string previously returned by `literllm_liter_llm_error_error_type`.
/// Passing a null pointer is a no-op.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn literllm_liter_llm_error_error_type_free(ptr: *mut std::ffi::c_char) {
    if !ptr.is_null() {
        // SAFETY: `ptr` was allocated by `CString::into_raw` inside
        // `literllm_liter_llm_error_error_type` and is now being reclaimed by the matching
        // `CString::from_raw`.  Passing null is explicitly allowed.
        unsafe { drop(std::ffi::CString::from_raw(ptr)) };
    }
}
